local OverseaTowerRankDialog = Class("OverseaTowerRankDialog")

function OverseaTowerRankDialog:__init()
    self.selectType = Constants.TowerType.Main
end

function OverseaTowerRankDialog:__delete()
    self.controller = nil
end

function OverseaTowerRankDialog:Awake()
    self:InitToggleData()
    CfUtils.SetActive(self.RT_MyRankNode, false)
end

function OverseaTowerRankDialog:InitToggleData()
    self._toggleData = {}
    local t = CfUtils.GetCf(AutoIds.IdSetting6020, "TowerTypeVo", true)
    for i, v in pairs(t) do
        table.insert(self._toggleData, {
            text = v.name,
            func = function()
                self.selectType = checkNumber(v.id)
                self:FreshUI()
            end
        })
    end
end

function OverseaTowerRankDialog:FreshUI()
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            cs_coroutine.yield_return(self:RequestRank())
            if IsNull(self.rankData) or #self.rankData == 0 then
                self:LoopModeFreshRankCellList(0)
                self:ShowBlank()
            else
                --KTool.SetActive(self.RT_MyRankNode, #self.rankData > 0)
                KTool.SetActive(self.RT_EmptyNode, not (#self.rankData > 0))
                self:UpdateMyselfCell()
                self:LoopModeFreshRankCellList(#self.rankData)
            end
        end)
    end)
end

function OverseaTowerRankDialog:OnShow()
    xTry(function()
        self:InitTabToggle()
        if IsNull(self.rankData) or #self.rankData == 0 then
            self:ShowBlank()
        else
            self:UpdateMyselfCell()
            self:LoopModeFreshRankCellList(#self.rankData)
        end
    end)
end

function OverseaTowerRankDialog:InitTabToggle()
    ---@type CommonTabToggleUp
    local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, 'Game.Behaviours.CommonTabToggleUp')
    env:FillToggles(self._toggleData, self.selectType)
end

function OverseaTowerRankDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local params = self.controller.Argument.parameters
        if isNotNull(params) and isNotNull(params.type) then
            self.selectType = checkNumber(params.type)
        end
        cs_coroutine.yield_return(self:RequestRank())
    end))
    return coWait
end

function OverseaTowerRankDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

