--- 构造我自己的rank信息
---@param rank any
function OverseaTowerRankDialog:GetMyselfRankInfo()
    local questId = OverseaTowerUtils.GetCurQuestId(self.selectType)
    local myselfInfo = LadderStruggleUtils.GetMyselfPlayerInfo(questId)
    myselfInfo.ranking = self.myRank
    myselfInfo.percentageRank = self.percentageRank
    myselfInfo.isMyself = true

    return myselfInfo
end

--- 获取我的队伍战力
function OverseaTowerRankDialog:GetMyselfCombatValue()
    local cardComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local teams = teamComponent:GetTeamInfoByQuestId(self.component.questId)

    local totalCombatValue = 0
    for i, teamInfo in ipairs(teams) do
        for j, teamDojo in ipairs(teamInfo.cardsInfo) do
            local cardData = cardComponent:GetCardById(teamDojo.refId)
            if not isNull(cardData) then
                totalCombatValue = totalCombatValue + FormulaUtils.GetCardFightingStrengthen(cardData, {}, false)
            end
        end
    end

    return totalCombatValue
end

--- 把服务器数据格式，转换为cell需要的格式
---@param data any
function OverseaTowerRankDialog:ConvertData(data)
    if isNull(data) then
        return
    end
    if not IsNull(data.converted) then
        return data
    end
    if data.team then
        local team = {}

        for index, teamInfo in pairs(data.team) do
            teamInfo.teamTitle = localize("队伍_num_", {_num_ = index})
            team[checkInt(index)] = teamInfo
        end

        data.team = team
    end
    data.converted = 1

    return data
end

--- 把我自己的数据，转换为cell需要的格式
---@param data any
function OverseaTowerRankDialog:ConvertMySelfData(data)
    if isNull(data) then
        return
    end
    for i, teamInfo in ipairs(data.team) do
        teamInfo.teamTitle = localize("队伍_num_", {_num_ = i})
    end
    return data
end

--- 请求排行榜
function OverseaTowerRankDialog:RequestRank()
    local succeed = false
    local operation = GameUtils.Request(Interfaces.OverseaClimbingTowerRank, {type = checkNumber(self.selectType)}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succeed = true
        local jsonData = response.data
        self.rankData = self:RankDictToList(jsonData.rankInfo)
        self.myRank = checkNumber(jsonData.myRanking)
        self.percentageRank = checkNumber(jsonData.percentageRank)
    end)

    while not succeed do
        cs_coroutine.yield_return()
    end

    if not succeed then
        self.rankData = {}
        self.myRank = 101
        self.percentageRank = 10
    end
end

--- 把服务器下发的字典转化为列表
---@param rankDict any
function OverseaTowerRankDialog:RankDictToList(rankDict)
    local rankList = {}
    for rank, rankInfo in pairs(rankDict) do
        rankInfo.rank = rank
        table.insert(rankList, rankInfo)
    end

    table.sort(rankList, function(a,b)
        return a.rank < b.rank
    end)

    return rankList
end

return OverseaTowerRankDialog